    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Avoid division by zero
    if (1 + EMP) <= 0:
        space_penalty = float('inf')
    else:
        space_penalty = (RI / (1 + EMP)) * 0.3

    if (1 + RI) <= 0:
        blocking_impact = float('inf')
    else:
        blocking_impact = ((AVG - CUR) / (1 + RI)) * (1 / (1 + SH)) * 0.2

